code.C:
#include <stdio.h>

int main() {
    int a, b;
    if (scanf("%d %d", &a, &b) == 2) {
        int start = (a % 2 == 0) ? a : a + 1;
        int first = 1;
        for (int i = start; i <= b; i += 2) {
            if (!first) printf(" ");
            printf("%d", i);
            first = 0;
        }
        printf("\n");
    }
    return 0;
}

