def main():
    parts = sys.stdin.read().split()
    if len(parts) >= 2:
        a, b = int(parts[0]), int(parts[1])
        start = a if a % 2 == 0 else a + 1
        print(' '.join(str(i) for i in range(start, b + 1, 2)))

